package repo

import (
	"errors"
	"net/http"
)

// IngestResult tells what a format's Ingest did with one artifact.
type IngestResult string

const (
	// Ingested means the artifact was stored.
	Ingested IngestResult = "ingested"
	// Skipped means an identical artifact was already stored (or the path is
	// generated by Command Center), so nothing changed.
	Skipped IngestResult = "skipped"
)

// IngestConflict is the error for an artifact that exists with different
// content; ingesting never overwrites.
func IngestConflict(format string, args ...any) error {
	return Errorf(http.StatusConflict, format, args...)
}

// IsIngestConflict reports whether err came from IngestConflict.
func IsIngestConflict(err error) bool {
	var e *Error
	return errors.As(err, &e) && e.Status == http.StatusConflict
}
